mapper.select:
        select
        orders.*,
        user.nick_name,
        user.avatar,
        beautyProjects.title,
        beautician.job_id,
        beautician.name
        from orders orders
        left join user user on orders.user_id = user.id
		left join beauty_projects beautyProjects on orders.project_id = beautyProjects.id
		left join beautician beautician on orders.beautician_id = beautician.id

            and orders.id = #{id}
            and orders.user_id = #{userId}
            and orders.project_id = #{projectId}
            and orders.order_no like concat('%',#{orderNo},'%')
            and orders.beautician_id = #{beauticianId}
            and orders.money = #{money}
            and orders.status = #{status}
            and orders.create_time = #{createTime}
            and orders.end_time = #{endTime}
            and user.nick_name like concat('%',#{nickName},'%')
            and user.avatar = #{avatar}
            and beautyProjects.title like concat('%',#{title},'%')
            and beautician.job_id = #{jobId}
            and beautician.name like concat('%',#{name},'%')
            and DATE_FORMAT(orders.create_time, '%Y-%m') = #{month}



            limit #{current},#{pageSize}

        select count(*) from orders orders
        left join user user on orders.user_id = user.id
		left join beauty_projects beautyProjects on orders.project_id = beautyProjects.id
		left join beautician beautician on orders.beautician_id = beautician.id

            and orders.id = #{id}
            and orders.user_id = #{userId}
            and orders.project_id = #{projectId}
            and orders.order_no like concat('%',#{orderNo},'%')
            and orders.beautician_id = #{beauticianId}
            and orders.money = #{money}
            and orders.status = #{status}
            and orders.create_time = #{createTime}
            and orders.end_time = #{endTime}
            and user.nick_name like concat('%',#{nickName},'%')
            and user.avatar = #{avatar}
            and beautyProjects.title like concat('%',#{title},'%')
            and beautician.job_id = #{jobId}
            and beautician.name like concat('%',#{name},'%')
            and DATE_FORMAT(orders.create_time, '%Y-%m') = #{month}
